WITH web_events_by_session AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(page))) AS page_values, MIN(event_time) AS first_event_time FROM web_events WHERE event_type IN ('search', 'page_view') GROUP BY session_id) SELECT s.id, s.browser, webs.page_values, webs.first_event_time FROM sessions s JOIN web_events_by_session webs ON s.id = webs.session_id ORDER BY browser, id LIMIT 10;
